+{"version":3,"sources":["/workspace/repo/packages/nx/src/utils/output.ts"],"sourcesContent":["import * as pc from 'picocolors';\nimport { EOL } from 'os';\nimport * as readline from 'readline';\nimport type { TaskStatus } from '../tasks-runner/tasks-runner';\n\nconst GH_GROUP_PREFIX = '::group::';\nconst GH_GROUP_SUFFIX = '::endgroup::';\n\nexport interface CLIErrorMessageConfig {\n  title: string;\n  bodyLines?: string[];\n  slug?: string;\n}\n\nexport interface CLIWarnMessageConfig {\n  title: string;\n  bodyLines?: string[];\n  slug?: string;\n}\n\nexport interface CLINoteMessageConfig {\n  title: string;\n  bodyLines?: string[];\n}\n\nexport interface CLISuccessMessageConfig {\n  title: string;\n  bodyLines?: string[];\n}\n\n/**\n * Custom orange color using ANSI 256-color code 214.\n * picocolors does not support keyword-based colors like chalk,\n * so orange is implemented manually.\n */\nexport function orange(text: string): string {\n  return pc.isColorSupported ? `\\x1b[38;5;214m${text}\\x1b[39m` : String(text);\n}\n\n/**\n * Map of color names to picocolors functions, used for dynamic color access.\n */\nconst pcColors: Record<string, (text: string) => string> = {\n  cyan: pc.cyan,\n  red: pc.red,\n  yellow: pc.yellow,\n  green: pc.green,\n  gray: pc.gray,\n  white: pc.white,\n  blue: pc.blue,\n  magenta: pc.magenta,\n  orange,\n};\n\nclass CLIOutput {\n  cliName = 'NX';\n  formatCommand = (taskId: string) => `${pc.dim('nx run')} ${taskId}`;\n\n  /**\n   * Longer dash character which forms more of a continuous line when place side to side\n   * with itself, unlike the standard dash character\n   */\n  private get VERTICAL_SEPARATOR() {\n    let divider = '';\n    for (let i = 0; i < process.stdout.columns - 1; i++) {\n      divider += '\\u2014';\n    }\n    return divider;\n  }\n\n  /**\n   * Expose some color and other utility functions so that other parts of the codebase that need\n   * more fine-grained control of message bodies are still using a centralized\n   * implementation.\n   */\n  colors = {\n    gray: pc.gray,\n    green: pc.green,\n    red: pc.red,\n    cyan: pc.cyan,\n    white: pc.white,\n    orange,\n  };\n  bold = pc.bold;\n  underline = pc.underline;\n  dim = pc.dim;\n\n  private writeToStdOut(str: string) {\n    process.stdout.write(str);\n  }\n\n  overwriteLine(lineText: string = '') {\n    // Ensure we always start writing from column 0.\n    readline.cursorTo(process.stdout, 0);\n    // this replaces the existing text up to the new line length\n    process.stdout.write(lineText);\n    // clear whatever text might be left to the right of the cursor (happens\n    // when existing text was longer than new one)\n    readline.clearLine(process.stdout, 1);\n    // Move to the next line and re-anchor to column 0 without relying on\n    // terminal newline translation behavior.\n    process.stdout.write('\\n');\n    readline.cursorTo(process.stdout, 0);\n  }\n\n  private writeOutputTitle({\n    color,\n    title,\n  }: {\n    color: string;\n    title: string;\n  }): void {\n    this.writeToStdOut(`${this.applyNxPrefix(color, title)}${EOL}`);\n  }\n\n  private writeOptionalOutputBody(bodyLines?: string[]): void {\n    if (!bodyLines) {\n      return;\n    }\n    this.addNewline();\n    bodyLines.forEach((bodyLine) => this.writeToStdOut(`${bodyLine}${EOL}`));\n  }\n\n  applyNxPrefix(color = 'cyan', text: string): string {\n    const colorFn = pcColors[color] || ((t: string) => t);\n    const nxPrefix = pc.inverse(pc.bold(colorFn(` ${this.cliName} `)));\n    return `${nxPrefix}  ${text}`;\n  }\n\n  addNewline() {\n    this.writeToStdOut(EOL);\n  }\n\n  addVerticalSeparator(color = 'gray') {\n    this.addNewline();\n    this.addVerticalSeparatorWithoutNewLines(color);\n    this.addNewline();\n  }\n\n  addVerticalSeparatorWithoutNewLines(color = 'gray') {\n    this.writeToStdOut(`${this.getVerticalSeparator(color)}${EOL}`);\n  }\n\n  getVerticalSeparatorLines(color = 'gray') {\n    return ['', this.getVerticalSeparator(color), ''];\n  }\n\n  private getVerticalSeparator(color: string): string {\n    const colorFn = pcColors[color] || ((t: string) => t);\n    return pc.dim(colorFn(this.VERTICAL_SEPARATOR));\n  }\n\n  error({ title, slug, bodyLines }: CLIErrorMessageConfig) {\n    this.addNewline();\n\n    this.writeOutputTitle({\n      color: 'red',\n      title: pc.red(title),\n    });\n\n    this.writeOptionalOutputBody(bodyLines);\n\n    /**\n     * Optional slug to be used in an Nx error message redirect URL\n     */\n    if (slug && typeof slug === 'string') {\n      this.addNewline();\n      this.writeToStdOut(\n        `${pc.gray(\n          '  Learn more about this error: '\n        )}https://errors.nx.dev/${slug}${EOL}`\n      );\n    }\n\n    this.addNewline();\n  }\n\n  warn({ title, slug, bodyLines }: CLIWarnMessageConfig) {\n    this.addNewline();\n\n    this.writeOutputTitle({\n      color: 'yellow',\n      title: pc.yellow(title),\n    });\n\n    this.writeOptionalOutputBody(bodyLines);\n\n    /**\n     * Optional slug to be used in an Nx warning message redirect URL\n     */\n    if (slug && typeof slug === 'string') {\n      this.addNewline();\n      this.writeToStdOut(\n        `${pc.gray(\n          '  Learn more about this warning: '\n        )}https://errors.nx.dev/${slug}${EOL}`\n      );\n    }\n\n    this.addNewline();\n  }\n\n  note({ title, bodyLines }: CLINoteMessageConfig) {\n    this.addNewline();\n\n    this.writeOutputTitle({\n      color: 'orange',\n      title: orange(title),\n    });\n\n    this.writeOptionalOutputBody(bodyLines);\n\n    this.addNewline();\n  }\n\n  success({ title, bodyLines }: CLISuccessMessageConfig) {\n    this.addNewline();\n\n    this.writeOutputTitle({\n      color: 'green',\n      title: pc.green(title),\n    });\n\n    this.writeOptionalOutputBody(bodyLines);\n\n    this.addNewline();\n  }\n\n  logSingleLine(message: string) {\n    this.addNewline();\n\n    this.writeOutputTitle({\n      color: 'gray',\n      title: message,\n    });\n\n    this.addNewline();\n  }\n\n  logRawLine(message: string) {\n    this.writeToStdOut(`${message}${EOL}`);\n    this.addNewline();\n  }\n\n  logCommand(message: string, taskStatus?: TaskStatus) {\n    this.addNewline();\n    this.writeToStdOut(this.getCommandWithStatus(message, taskStatus));\n    this.addNewline();\n    this.addNewline();\n  }\n\n  logCommandOutput(message: string, taskStatus: TaskStatus, output: string) {\n    let commandOutputWithStatus = this.getCommandWithStatus(\n      message,\n      taskStatus\n    );\n\n    if (\n      process.env.NX_SKIP_LOG_GROUPING !== 'true' &&\n      process.env.GITHUB_ACTIONS\n    ) {\n      const icon = this.getStatusIcon(taskStatus);\n      commandOutputWithStatus = `${GH_GROUP_PREFIX}${icon} ${commandOutputWithStatus}`;\n    }\n\n    this.addNewline();\n    this.writeToStdOut(commandOutputWithStatus);\n    this.addNewline();\n    this.addNewline();\n    this.writeToStdOut(output);\n\n    if (\n      process.env.NX_SKIP_LOG_GROUPING !== 'true' &&\n      process.env.GITHUB_ACTIONS\n    ) {\n      this.writeToStdOut(GH_GROUP_SUFFIX);\n    }\n  }\n\n  private getCommandWithStatus(\n    message: string,\n    taskStatus: TaskStatus\n  ): string {\n    const commandOutput =\n      pc.dim('> ') + this.formatCommand(this.normalizeMessage(message));\n    return this.addTaskStatus(taskStatus, commandOutput);\n  }\n\n  private getStatusIcon(taskStatus: TaskStatus) {\n    switch (taskStatus) {\n      case 'success':\n        return '✅';\n      case 'failure':\n        return '❌';\n      case 'skipped':\n      case 'local-cache-kept-existing':\n        return '⏩';\n      case 'local-cache':\n      case 'remote-cache':\n        return '🔁';\n    }\n  }\n\n  private normalizeMessage(message: string) {\n    if (message.startsWith('nx run ')) {\n      return message.substring('nx run '.length);\n    } else if (message.startsWith('run ')) {\n      return message.substring('run '.length);\n    } else {\n      return message;\n    }\n  }\n\n  private addTaskStatus(taskStatus: TaskStatus, commandOutput: string) {\n    if (taskStatus === 'local-cache') {\n      return `${commandOutput}  ${pc.dim('[local cache]')}`;\n    } else if (taskStatus === 'remote-cache') {\n      return `${commandOutput}  ${pc.dim('[remote cache]')}`;\n    } else if (taskStatus === 'local-cache-kept-existing') {\n      return `${commandOutput}  ${pc.dim(\n        '[existing outputs match the cache, left as is]'\n      )}`;\n    } else {\n      return commandOutput;\n    }\n  }\n\n  log({ title, bodyLines, color }: CLIWarnMessageConfig & { color?: string }) {\n    this.addNewline();\n\n    const colorFn = color ? pcColors[color] : undefined;\n    this.writeOutputTitle({\n      color: 'cyan',\n      title: colorFn ? colorFn(title) : title,\n    });\n\n    this.writeOptionalOutputBody(bodyLines);\n\n    this.addNewline();\n  }\n\n  drain(): Promise<void> {\n    return new Promise((resolve) => {\n      if (process.stdout.writableNeedDrain) {\n        process.stdout.once('drain', resolve);\n      } else {\n        resolve();\n      }\n    });\n  }\n}\n\nexport const output = new CLIOutput();\n"],"names":["orange","output","GH_GROUP_PREFIX","GH_GROUP_SUFFIX","text","pc","isColorSupported","String","pcColors","cyan","red","yellow","green","gray","white","blue","magenta","CLIOutput","VERTICAL_SEPARATOR","divider","i","process","stdout","columns","writeToStdOut","str","write","overwriteLine","lineText","readline","cursorTo","clearLine","writeOutputTitle","color","title","applyNxPrefix","EOL","writeOptionalOutputBody","bodyLines","addNewline","forEach","bodyLine","colorFn","t","nxPrefix","inverse","bold","cliName","addVerticalSeparator","addVerticalSeparatorWithoutNewLines","getVerticalSeparator","getVerticalSeparatorLines","dim","error","slug","warn","note","success","logSingleLine","message","logRawLine","logCommand","taskStatus","getCommandWithStatus","logCommandOutput","commandOutputWithStatus","env","NX_SKIP_LOG_GROUPING","GITHUB_ACTIONS","icon","getStatusIcon","commandOutput","formatCommand","normalizeMessage","addTaskStatus","startsWith","substring","length","log","undefined","drain","Promise","resolve","writableNeedDrain","once","taskId","colors","underline"],"mappings":";;;;oEAAoB;oBACA;kEACM;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAiCVA;;;eAAAA;;;QAAAA;;;;+BA6THC;;;eAAAA;;;QAAAA;;;;AA3Vb,MAAMC,kBAAkB;AACxB,MAAMC,kBAAkB;AA6BjB,SAASH,OAAOI,IAAY;IACjC,OAAOC,YAAGC,gBAAgB,GAAG,CAAC,cAAc,EAAEF,KAAK,QAAQ,CAAC,GAAGG,OAAOH;AACxE;AAEA;;CAEC,GACD,MAAMI,WAAqD;IACzDC,MAAMJ,YAAGI,IAAI;IACbC,KAAKL,YAAGK,GAAG;IACXC,QAAQN,YAAGM,MAAM;IACjBC,OAAOP,YAAGO,KAAK;IACfC,MAAMR,YAAGQ,IAAI;IACbC,OAAOT,YAAGS,KAAK;IACfC,MAAMV,YAAGU,IAAI;IACbC,SAASX,YAAGW,OAAO;IACnBhB;AACF;AAEA,MAAMiB;IAIJ;;;GAGC,GACD,IAAYC,qBAAqB;QAC/B,IAAIC,UAAU;QACd,IAAK,IAAIC,IAAI,GAAGA,IAAIC,QAAQC,MAAM,CAACC,OAAO,GAAG,GAAGH,IAAK;YACnDD,WAAW;QACb;QACA,OAAOA;IACT;IAmBQK,cAAcC,GAAW,EAAE;QACjCJ,QAAQC,MAAM,CAACI,KAAK,CAACD;IACvB;IAEAE,cAAcC,WAAmB,EAAE,EAAE;QACnC,gDAAgD;QAChDC,UAASC,QAAQ,CAACT,QAAQC,MAAM,EAAE;QAClC,4DAA4D;QAC5DD,QAAQC,MAAM,CAACI,KAAK,CAACE;QACrB,wEAAwE;QACxE,8CAA8C;QAC9CC,UAASE,SAAS,CAACV,QAAQC,MAAM,EAAE;QACnC,qEAAqE;QACrE,yCAAyC;QACzCD,QAAQC,MAAM,CAACI,KAAK,CAAC;QACrBG,UAASC,QAAQ,CAACT,QAAQC,MAAM,EAAE;IACpC;IAEQU,iBAAiB,EACvBC,KAAK,EACLC,KAAK,EAIN,EAAQ;QACP,IAAI,CAACV,aAAa,CAAC,GAAG,IAAI,CAACW,aAAa,CAACF,OAAOC,SAASE,OAAG,EAAE;IAChE;IAEQC,wBAAwBC,SAAoB,EAAQ;QAC1D,IAAI,CAACA,WAAW;YACd;QACF;QACA,IAAI,CAACC,UAAU;QACfD,UAAUE,OAAO,CAAC,CAACC,WAAa,IAAI,CAACjB,aAAa,CAAC,GAAGiB,WAAWL,OAAG,EAAE;IACxE;IAEAD,cAAcF,QAAQ,MAAM,EAAE7B,IAAY,EAAU;QAClD,MAAMsC,UAAUlC,QAAQ,CAACyB,MAAM,IAAK,CAAA,CAACU,IAAcA,CAAAA;QACnD,MAAMC,WAAWvC,YAAGwC,OAAO,CAACxC,YAAGyC,IAAI,CAACJ,QAAQ,CAAC,CAAC,EAAE,IAAI,CAACK,OAAO,CAAC,CAAC,CAAC;QAC/D,OAAO,GAAGH,SAAS,EAAE,EAAExC,MAAM;IAC/B;IAEAmC,aAAa;QACX,IAAI,CAACf,aAAa,CAACY,OAAG;IACxB;IAEAY,qBAAqBf,QAAQ,MAAM,EAAE;QACnC,IAAI,CAACM,UAAU;QACf,IAAI,CAACU,mCAAmC,CAAChB;QACzC,IAAI,CAACM,UAAU;IACjB;IAE