erridesRows.push(arg));\n      }\n\n      const pinnedFooterLines = [\n        output.applyNxPrefix('cyan', output.colors.cyan(text)),\n        ...taskOverridesRows,\n        ...additionalFooterRows,\n      ];\n\n      // Vertical breathing room when there isn't yet any output or divider\n      if (!hasTaskOutput) {\n        pinnedFooterLines.unshift('');\n      }\n\n      renderPinnedFooter(pinnedFooterLines);\n    } else {\n      renderPinnedFooter([]);\n    }\n  };\n\n  lifeCycle.startCommand = () => {\n    if (projectNames.length <= 0) {\n      renderPinnedFooter([\n        '',\n        output.applyNxPrefix(\n          'gray',\n          `No projects with ${formatTargetsAndProjects(\n            projectNames,\n            targets,\n            tasks\n          )} were run`\n        ),\n      ]);\n      resolveRenderIsDonePromise();\n      return;\n    }\n    renderPinnedFooter([]);\n  };\n\n  lifeCycle.endCommand = () => {\n    clearRenderInterval();\n    const timeTakenText = prettyTime(process.hrtime(start));\n\n    moveCursorToStartOfPinnedFooter();\n    if (totalTasks === 0) {\n      renderPinnedFooter([output.applyNxPrefix('gray', 'No tasks were run')]);\n      resolveRenderIsDonePromise();\n      return;\n    }\n    if (totalSuccessfulTasks === totalTasks) {\n      const text = `Successfully ran ${formatTargetsAndProjects(\n        projectNames,\n        targets,\n        tasks\n      )}`;\n      const taskOverridesRows = [];\n      const filteredOverrides = Object.entries(overrides).filter(\n        // Don't print the data passed through from the version subcommand to the publish executor options, it could be quite large and it's an implementation detail.\n        ([flag]) => flag !== 'nxReleaseVersionData'\n      );\n      if (filteredOverrides.length > 0) {\n        taskOverridesRows.push('');\n        taskOverridesRows.push(\n          `${EXTENDED_LEFT_PAD}${pc.dim(pc.green('With additional flags:'))}`\n        );\n        filteredOverrides\n          .map(([flag, value]) =>\n            pc.dim(pc.green(formatFlags(EXTENDED_LEFT_PAD, flag, value)))\n          )\n          .forEach((arg) => taskOverridesRows.push(arg));\n      }\n\n      const pinnedFooterLines = [\n        output.applyNxPrefix(\n          'green',\n          output.colors.green(text) + pc.dim(pc.white(` (${timeTakenText})`))\n        ),\n        ...taskOverridesRows,\n      ];\n      if (totalCachedTasks > 0) {\n        pinnedFooterLines.push(\n          output.dim(\n            `${EOL}Nx read the output from the cache instead of running the command for ${totalCachedTasks} out of ${totalTasks} tasks.`\n          )\n        );\n      }\n      renderPinnedFooter(pinnedFooterLines, 'green');\n    } else {\n      const text = `Ran ${formatTargetsAndProjects(\n        projectNames,\n        targets,\n        tasks\n      )}`;\n      const taskOverridesRows = [];\n      const filteredOverrides = Object.entries(overrides).filter(\n        // Don't print the data passed through from the version subcommand to the publish executor options, it could be quite large and it's an implementation detail.\n        ([flag]) => flag !== 'nxReleaseVersionData'\n      );\n      if (filteredOverrides.length > 0) {\n        taskOverridesRows.push('');\n        taskOverridesRows.push(\n          `${EXTENDED_LEFT_PAD}${pc.dim(pc.red('With additional flags:'))}`\n        );\n        filteredOverrides\n          .map(([flag, value]) =>\n            pc.dim(pc.red(formatFlags(EXTENDED_LEFT_PAD, flag, value)))\n          )\n          .forEach((arg) => taskOverridesRows.push(arg));\n      }\n\n      const numFailedToPrint = 5;\n      const failedTasksForPrinting = Array.from(failedTasks).slice(\n        0,\n        numFailedToPrint\n      );\n      const failureSummaryRows = [\n        output.applyNxPrefix(\n          'red',\n          output.colors.red(text) + pc.dim(pc.white(` (${timeTakenText})`))\n        ),\n        ...taskOverridesRows,\n        '',\n        output.dim(\n