+import { Migrator, formatCommandFailure } from './src/command-line/migrate/migrate';
+
+const pkgJson = { name: 'w', version: '0.0.0', dependencies: { child: '1.0.0' } } as any;
+
+describe('new behavior', () => {
+  it('throws when top-level config missing version', async () => {
+    const m = new Migrator({
+      packageJson: pkgJson,
+      getInstalledPackageVersion: () => '1.0.0',
+      fetch: () => Promise.resolve({} as any),
+      from: {}, to: {},
+    });
+    await expect(m.migrate('mypackage', '2.0.0')).rejects.toThrow(
+      'Fetched migration metadata for mypackage is invalid: the target version is missing.'
+    );
+  });
+
+  it('throws when applied child update missing version (requires met)', async () => {
+    const m = new Migrator({
+      packageJson: pkgJson,
+      getInstalledPackageVersion: () => '1.0.0',
+      fetch: (p) => p === 'parent'
+        ? Promise.resolve({ version: '2.0.0', packageJsonUpdates: {
+            v2: { version: '2.0.0', requires: { child: '1.0.0' }, packages: { child: { version: undefined } as any } },
+          } } as any)
+        : Promise.resolve({ version: '2.0.0' } as any),
+      from: {}, to: {},
+    });
+    await expect(m.migrate('parent', '2.0.0')).rejects.toThrow(
+      'Fetched migration metadata for parent is invalid: the target version for child is missing.'
+    );
+  });
+
+  it('does NOT throw when group skipped (requires unmet)', async () => {
+    const m = new Migrator({
+      packageJson: pkgJson,
+      getInstalledPackageVersion: () => '1.0.0',
+      fetch: (p) => p === 'parent'
+        ? Promise.resolve({ version: '2.0.0', packageJsonUpdates: {
+            v2: { version: '2.0.0', requires: { child: '99.0.0' }, packages: { child: { version: undefined } as any } },
+          } } as any)
+        : Promise.resolve({ version: '2.0.0' } as any),
+      from: {}, to: {},
+    });
+    expect(await m.migrate('parent', '2.0.0')).toEqual({
+      migrations: [],
+      packageUpdates: { parent: { version: '2.0.0', addToPackageJson: false } },
+    });
+  });
+
+  it('formatCommandFailure', () => {
+    expect(formatCommandFailure('cmd', { message: 'm', stderr: 'e' })).toBe('m\ne');
+    expect(formatCommandFailure('cmd', { message: 'm\nline2' })).toBe('m\nline2');
+    expect(formatCommandFailure('cmd', { message: 'm', stderr: '' })).toBe('m');
+  });
+});
